package com.reactur.backend.config;

import io.swagger.v3.oas.annotations.OpenAPIDefinition;
import io.swagger.v3.oas.annotations.enums.SecuritySchemeIn;
import io.swagger.v3.oas.annotations.enums.SecuritySchemeType;
import io.swagger.v3.oas.annotations.info.Info;
import io.swagger.v3.oas.annotations.security.SecurityRequirement;
import io.swagger.v3.oas.annotations.security.SecurityScheme;
import org.springframework.context.annotation.Configuration;

/**
 * API metadata for the OpenAPI description auto-generated by "springdoc-openapi".
 * <p>
 * Reachable at {@code /v3/api-docs} (raw OpenAPI JSON) and {@code /swagger-ui.html} (interactive
 * Swagger UI) once the application is running.
 * <p>
 * The {@code bearer-jwt} security scheme below tells Swagger UI to show an "Authorize"
 * button to attach a token as an {@code Authorization: Bearer <token>} header, in
 * order to be able to test the autorisation-protected endpoints.
 */
@Configuration
@OpenAPIDefinition(
  info = @Info(
    title = "ReacTUr Backend API",
    description = "Backend REST API for the ReacTUr database " +
      "(reactants, structures, experiments, and their metadata/attachments)",
    version = "v1"  // TODO-Deploy: Decide mechanism (instead of hard-coding) to track version number
  ),
  security = @SecurityRequirement(name = "bearerAuth")
)
@SecurityScheme(
  name = "bearerAuth",
  type = SecuritySchemeType.HTTP,
  scheme = "bearer",
  bearerFormat = "JWT",
  in = SecuritySchemeIn.HEADER
)
public class OpenApiConfig {
}
